# Write the parser file in chunks
with open('/app/src/sql/parser/parser.rs', 'w') as f:
    f.write('use std::iter::Peekable;
')
    f.write('use std::ops::Add;

')
    f.write('use super::{Keyword, Lexer, Token, ast};
')
    f.write('use crate::errinput;
')
    f.write('use crate::error::Result;
')
    f.write('use crate::sql::types::DataType;

')
    f.write('pub struct Parser<'a> {
')
    f.write('    pub lexer: Peekable<Lexer<'a>>,
')
    f.write('}

')
    f.write('impl Parser<'_> {
')
    f.write('    pub fn parse(statement: &str) -> Result<ast::Statement> {
')
    f.write('        let mut parser = Parser::new(statement);
')
    f.write('        let stmt = parser.parse_statement()?;
')
    f.write('        if let Some(token) = parser.peek()? {
')
    f.write('            if !matches!(token, Token::Semicolon) {
')
    f.write('                return errinput!("unexpected token after statement: {}", token);
')
    f.write('            }
')
    f.write('        }
')
    f.write('        Ok(stmt)
')
    f.write('    }

')
    f.write('    #[cfg(test)]
')
    f.write('    pub fn parse_expr(expr: &str) -> Result<ast::Expression> {
')
    f.write('        let mut parser = Parser::new(expr);
')
    f.write('        let expr = parser.parse_expression()?;
')
    f.write('        if parser.peek()?.is_some() {
')
    f.write('            return errinput!("unexpected tokens after expression");
')
    f.write('        }
')
    f.write('        Ok(expr)
')
    f.write('    }

')
    f.write('    fn new(input: &str) -> Parser<'_> {
')
    f.write('        Parser {
')
    f.write('            lexer: Lexer::new(input).peekable(),
')
    f.write('        }
')
    f.write('    }

')
    f.write('    fn next(&mut self) -> Result<Token> {
')
    f.write('        self.lexer.next().unwrap_or_else(|| errinput!("unexpected end of input"))
')
    f.write('    }

')
    f.write('    fn next_ident(&mut self) -> Result<String> {
')
    f.write('        match self.next()? {
')
    f.write('            Token::Ident(name) => Ok(name),
')
    f.write('            Token::Keyword(k) => Ok(k.to_string()),
')
    f.write('            other => errinput!("expected identifier, got {}", other),
')
    f.write('        }
')
    f.write('    }

')
    f.write('    fn next_if(&mut self, predicate: impl Fn(&Token) -> bool) -> Option<Token> {
')
    f.write('        if self.lexer.peek().map_or(false, |t| predicate(t)) {
')
    f.write('            self.lexer.next().unwrap()
')
    f.write('        } else {
')
    f.write('            None
')
    f.write('        }
')
    f.write('    }

')
    f.write('    fn next_if_map<T>(&mut self, f: impl Fn(&Token) -> Option<T>) -> Option<T> {
')
    f.write('        if let Some(token) = self.lexer.peek() {
')
    f.write('            if let Some(result) = f(token) {
')
    f.write('                self.lexer.next();
')
    f.write('                return Some(result);
')
    f.write('            }
')
    f.write('        }
')
    f.write('        None
')
    f.write('    }

')
    f.write('    fn next_if_keyword(&mut self) -> Option<Keyword> {
')
    f.write('        self.next_if_map(|t| match t {
')
    f.write('            Token::Keyword(k) => Some(*k),
')
    f.write('            _ => None,
')
    f.write('        })
')
    f.write('    }

')
    f.write('    fn next_is(&mut self, token: Token) -> bool {
')
    f.write('        self.next_if(|t| t == &token).is_some()
')
    f.write('    }

')
    f.write('    fn expect(&mut self, expect: Token) -> Result<()> {
')
    f.write('        let token = self.next()?;
')
    f.write('        if token == expect {
')
    f.write('            Ok(())
')
    f.write('        } else {
')
    f.write('            errinput!("expected {}, got {}", expect, token)
')
    f.write('        }
')
    f.write('    }

')
    f.write('    fn skip(&mut self, token: Token) {
')
    f.write('        self.next_is(token);
')
    f.write('    }

')
    f.write('    fn peek(&mut self) -> Result<Option<&Token>> {
')
    f.write('        Ok(self.lexer.peek())
')
    f.write('    }
')
print('Part 1 done')
PYEND

